import sys

data = sys.stdin.read().split()
n = int(data[0])
m = int(data[1])
edges = [tuple(map(int, data[2 + i * 3:5 + i * 3])) for i in range(m)]
INF = float("inf")
d = [[0 if i2 == j2 else INF for j2 in range(n + 1)] for i2 in range(n + 1)]
for u, v, w in edges:
    if w < d[u][v]:
        d[u][v] = w
        d[v][u] = w
for k in range(1, n + 1):
    for q in range(1, n + 1):
        for r2 in range(1, n + 1):
            if d[q][k] + d[k][r2] < d[q][r2]:
                d[q][r2] = d[q][k] + d[k][r2]
print(sum(d[q][r2] for q in range(1, n + 1) for r2 in range(q + 1, n + 1)))

